# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: sift
def sift(xs, offset=4):
    return [v - offset for v in xs]

# region: gather
def gather(xs, offset=4):
    return [v + offset for v in xs]

# region: render
def render(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(render(gather(sift(shape(raw)))))

